<?php namespace PlayBrand\Performance; if(!defined('ABSPATH'))exit; final class Fonts { public static function init():void{add_action('wp_head',[self::class,'css'],2);}
 public static function css():void{$o=get_option(PBPF_OPTION,[]); if(empty($o['enabled'])||empty($o['fonts']))return; $dir=wp_upload_dir(); $path=trailingslashit($dir['basedir']).'playbrand-performance/fonts'; if(!is_dir($path))return; $files=glob($path.'/*.woff2')?:[]; if(!$files)return; echo "\n<style id=\"pbpf-fonts\">"; foreach($files as $f){$n=sanitize_title(pathinfo($f,PATHINFO_FILENAME));$u=trailingslashit($dir['baseurl']).'playbrand-performance/fonts/'.basename($f); printf('@font-face{font-family:%s;src:url(%s) format(\'woff2\');font-display:swap}',esc_attr($n),esc_url($u));} echo '</style>\n';}
}
